package com.digitalbase.ticketing.service;import com.digitalbase.ticketing.dto.*;import com.digitalbase.ticketing.enums.ProductStatus; // ---> Enum ကို Import လုပ်ထားပါသည် <---import com.digitalbase.ticketing.enums.TicketStatus;import com.digitalbase.ticketing.exception.ResourceNotFoundException;import com.digitalbase.ticketing.model.ClientProduct;import com.digitalbase.ticketing.model.Product;import com.digitalbase.ticketing.model.Ticket;import com.digitalbase.ticketing.model.User;import com.digitalbase.ticketing.repository.ClientProductRepository;import com.digitalbase.ticketing.repository.ProductRepository;import com.digitalbase.ticketing.repository.TicketRepository;import com.digitalbase.ticketing.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.time.Instant;import java.util.List;import java.util.stream.Collectors;@Service@RequiredArgsConstructorpublic class ClientProductServiceImpl implements ClientProductService {    private final ClientProductRepository clientProductRepository;    private final TicketRepository ticketRepository;    private final UserRepository userRepository;    private final ProductRepository productRepository;    @Override    public ClientProductResponse assignProductToClient(ClientProductRequest request) {        User user = userRepository.findById(request.getUserId())                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        Product product = productRepository.findById(request.getProductId())                .orElseThrow(() -> new ResourceNotFoundException("Product not found"));        // ဤ Customer သည် ဤ Product ကို ရရှိပြီးသား ဖြစ်နေပါက အသစ်ထပ်မပေးဘဲ Error ပြန်ပေးမည်        if (clientProductRepository.existsByUserIdAndProductId(user.getId(), product.getId())) {            throw new RuntimeException("This client already has the product: " + product.getName());        }        ClientProduct clientProduct = ClientProduct.builder()                .user(user)                .product(product)                .supportPlan(request.getSupportPlan())                .purchasedDate(Instant.now())                .planEndDate(request.getPlanEndDate())                .totalMinutes(request.getTotalMinutes())                .availableMinutes(request.getTotalMinutes())                .status(ProductStatus.ACTIVE) // 👈 ဤနေရာတွင် boolean အစား Enum ဖြင့် ပြင်ဆင်ထားသည်                .build();        ClientProduct savedClientProduct = clientProductRepository.save(clientProduct);        return mapToResponse(savedClientProduct);    }    // ================= [၁] Top Nav အတွက် သီးသန့် Method =================    @Override    @org.springframework.transaction.annotation.Transactional(readOnly = true)    public TopNavResponse getTopNavSummary(String email) {        User user = userRepository.findByEmail(email).orElseThrow();        List<ClientProduct> products = clientProductRepository.findAllByUserId(user.getId());        int totalMins = products.stream().mapToInt(p -> p.getTotalMinutes() != null ? p.getTotalMinutes() : 0).sum();        int availableMins = products.stream().mapToInt(p -> p.getAvailableMinutes() != null ? p.getAvailableMinutes() : 0).sum();        int displayAvailableMins = Math.max(0, availableMins);        String headerText = String.format("Available: %dHrs %d Mins/%d Hrs Credit",                displayAvailableMins / 60, displayAvailableMins % 60, totalMins / 60);        return TopNavResponse.builder()                .headerAvailableCreditText(headerText)                .fullName(user.getFullName())                .build();    }    // ================= [၂] Dashboard စာမျက်နှာအတွက် သီးသန့် Method =================    @Override    @org.springframework.transaction.annotation.Transactional(readOnly = true)    public DashboardSummaryResponse getDashboardSummary(String email) {        User user = userRepository.findByEmail(email).orElseThrow();        List<ClientProduct> products = clientProductRepository.findAllByUserId(user.getId());        int totalMins = 0;        int availableMins = 0;        int activeProductCount = 0;        ClientProduct activeProduct = null;        ClientProduct nearestExpiringProduct = null;        for (ClientProduct cp : products) {            totalMins += (cp.getTotalMinutes() != null ? cp.getTotalMinutes() : 0);            availableMins += (cp.getAvailableMinutes() != null ? cp.getAvailableMinutes() : 0);            if (cp.getStatus() == ProductStatus.ACTIVE || cp.getStatus() == ProductStatus.EXPIRING_SOON) {                activeProductCount++;                if (activeProduct == null) activeProduct = cp;                if (nearestExpiringProduct == null || cp.getPlanEndDate().isBefore(nearestExpiringProduct.getPlanEndDate())) {                    nearestExpiringProduct = cp;                    activeProduct = cp;                }            }        }        int displayAvailableMins = Math.max(0, availableMins);        int usedMinsTotal = Math.max(0, totalMins - displayAvailableMins);        int extraMinsTotal = availableMins < 0 ? Math.abs(availableMins) : 0;        long daysRemaining = 0;        String expiryString = "N/A";        if (nearestExpiringProduct != null && nearestExpiringProduct.getPlanEndDate() != null) {            daysRemaining = java.time.temporal.ChronoUnit.DAYS.between(Instant.now(), nearestExpiringProduct.getPlanEndDate());            if (daysRemaining < 0) daysRemaining = 0;            java.time.format.DateTimeFormatter formatter = java.time.format.DateTimeFormatter.ofPattern("'Expired in' MMM d")                    .withZone(java.time.ZoneId.systemDefault());            expiryString = formatter.format(nearestExpiringProduct.getPlanEndDate());        }        Instant startOfToday = java.time.LocalDate.now().atStartOfDay(java.time.ZoneId.systemDefault()).toInstant();        List<TicketStatus> submittedStatuses = java.util.Arrays.asList(TicketStatus.SUBMITTED);        long totalSubmitted = ticketRepository.countByCustomerIdAndStatusIn(user.getId(), submittedStatuses);        long todaySubmitted = ticketRepository.countByCustomerIdAndStatusInAndCreatedAtAfter(user.getId(), submittedStatuses, startOfToday);        List<TicketStatus> resolvedStatuses = java.util.Arrays.asList(TicketStatus.RESOLVED, TicketStatus.CLOSED);        long totalResolved = ticketRepository.countByCustomerIdAndStatusIn(user.getId(), resolvedStatuses);        long todayResolved = ticketRepository.countByCustomerIdAndStatusInAndUpdatedAtAfter(user.getId(), resolvedStatuses, startOfToday);        return DashboardSummaryResponse.builder()                .purchasedHours(totalMins / 60)                .usedHours(usedMinsTotal / 60)                .usedMinutes(usedMinsTotal % 60)                .availableHours(displayAvailableMins / 60)                .availableMinutes(displayAvailableMins % 60)                .extraHours(extraMinsTotal / 60)                .supportPlanName(activeProduct != null ? activeProduct.getSupportPlan() : "No Active Plan")                .status(activeProduct != null ? activeProduct.getStatus().name() : "DISABLED")                .purchasedDate(activeProduct != null ? activeProduct.getPurchasedDate() : null)                .planEndDate(activeProduct != null ? activeProduct.getPlanEndDate() : null)                .slaHoursCard(DashboardSummaryResponse.SlaHoursCard.builder()                        .totalHours(totalMins / 60)                        .usedHours(usedMinsTotal / 60)                        .usedMinutes(usedMinsTotal % 60)                        .remainingHours(displayAvailableMins / 60)                        .remainingMinutes(displayAvailableMins % 60)                        .expiryDateText(expiryString)                        .daysRemaining(daysRemaining)                        .build())                .submittedTicketsCard(DashboardSummaryResponse.TicketStatCard.builder()                        .totalCount((int) totalSubmitted)                        .todayCount((int) todaySubmitted)                        .build())                .resolvedTicketsCard(DashboardSummaryResponse.TicketStatCard.builder()                        .totalCount((int) totalResolved)                        .todayCount((int) todayResolved)                        .build())                .activeProductCard(DashboardSummaryResponse.ProductStatCard.builder()                        .activeCount(activeProductCount)                        .totalCount(products.size())                        .expiryDateText(expiryString)                        .daysRemaining(daysRemaining)                        .build())                .build();    }    @Override    public MyProductDashboardResponse getMyProducts(String email) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        // ၁။ Database မှ Client ၏ Product အားလုံးကို ဆွဲထုတ်ပါမည်        List<ClientProduct> clientProducts = clientProductRepository.findAllByUserId(user.getId());        // ၂။ Dashboard အတွက် လိုအပ်သော တွက်ချက်မှုများ ပြုလုပ်ပါမည်        int totalProducts = clientProducts.size();        // 👈 ACTIVE ဖြစ်နေတာရော၊ သက်တမ်းကုန်ခါနီး (EXPIRING_SOON) ဖြစ်နေတာပါ Active အနေဖြင့် ရေတွက်ပါမည်        int activeProducts = (int) clientProducts.stream()                .filter(cp -> cp.getStatus() == ProductStatus.ACTIVE || cp.getStatus() == ProductStatus.EXPIRING_SOON)                .count();        int totalSlaHours = clientProducts.stream()                .mapToInt(ClientProduct::getTotalMinutes)                .sum() / 60; // မိနစ်ကို နာရီပြောင်းခြင်း        // Available Minutes သည် အနှုတ်ပြနေပါက Extra သုံးထားသည်ဟု ယူဆပြီး ပေါင်းပါမည်        int extraUsageHours = clientProducts.stream()                .filter(cp -> cp.getAvailableMinutes() < 0)                .mapToInt(cp -> Math.abs(cp.getAvailableMinutes()))                .sum() / 60;        // ၃။ သင်၏ မူလ mapToResponse ကို အသုံးပြု၍ List ပြောင်းပါမည်        List<ClientProductResponse> productResponses = clientProducts.stream()                .map(this::mapToResponse)                .collect(Collectors.toList());        // ၄။ DTO အသစ်ဖြင့် အားလုံးကို ထုပ်ပိုးပြီး ပြန်ပေးပါမည်        return MyProductDashboardResponse.builder()                .totalProducts(totalProducts)                .totalSlaHours(totalSlaHours)                .activeProducts(activeProducts)                .extraUsageHours(extraUsageHours)                .products(productResponses)                .build();    }    @Override    public ClientProductDetailResponse getClientProductDetails(Long clientProductId, String email) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        ClientProduct cp = clientProductRepository.findByIdAndUserId(clientProductId, user.getId())                .orElseThrow(() -> new ResourceNotFoundException("Product not found or access denied"));        long daysRemaining = 0;        if (cp.getPlanEndDate() != null) {            daysRemaining = java.time.temporal.ChronoUnit.DAYS.between(Instant.now(), cp.getPlanEndDate());            if (daysRemaining < 0) daysRemaining = 0;        }        int totalMins = cp.getTotalMinutes() != null ? cp.getTotalMinutes() : 0;        int availMins = cp.getAvailableMinutes() != null ? cp.getAvailableMinutes() : 0;        int usedMinsTotal = availMins >= 0 ? totalMins - availMins : totalMins;        int remainMinsTotal = Math.max(availMins, 0);        int extraMinsTotal = availMins < 0 ? Math.abs(availMins) : 0;        ClientProductDetailResponse.SlaDetails slaDetails = ClientProductDetailResponse.SlaDetails.builder()                .totalSlaHours(totalMins / 60)                .remainingHours(remainMinsTotal / 60)                .remainingMinutes(remainMinsTotal % 60)                .usedHours(usedMinsTotal / 60)                .usedMinutes(usedMinsTotal % 60)                .extraHours(extraMinsTotal / 60)                .extraMinutes(extraMinsTotal % 60)                .daysRemaining(daysRemaining)                .planEndDate(cp.getPlanEndDate())                .build();        ClientProductDetailResponse.SystemMetadata metadata = ClientProductDetailResponse.SystemMetadata.builder()                .productType(cp.getProduct().getProductType())                .supportPlan(cp.getSupportPlan())                .purchasedDate(cp.getPurchasedDate())                .planEndDate(cp.getPlanEndDate())                .build();        return ClientProductDetailResponse.builder()                .productName(cp.getProduct().getName())                .productDescription(cp.getProduct().getDescription())                .status(cp.getStatus().name())                .slaDetails(slaDetails)                .metadata(metadata)                .build();    }    @Override    public List<ProductTicketDto> getProductRelatedTickets(Long clientProductId, String email) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        ClientProduct cp = clientProductRepository.findByIdAndUserId(clientProductId, user.getId())                .orElseThrow(() -> new ResourceNotFoundException("Product not found or access denied"));        List<Ticket> tickets = ticketRepository.findAllByClientProductId(cp.getId());        return tickets.stream().map(t ->                ProductTicketDto.builder()                        .ticketId("DB-TK" + t.getId())                        .status(t.getStatus().name())                        .issueType(t.getIssueType().name())                        .assignedTeam(t.getDeveloper() != null ? t.getDeveloper().getFullName() : "Pending")                        .priority(t.getPriority() != null ? t.getPriority().name() : "Normal")                        .timeUsedMinutes(t.getSpentMinutes() != null ? t.getSpentMinutes() : 0)                        .build()        ).collect(Collectors.toList());    }    private ClientProductResponse mapToResponse(ClientProduct cp) {        return ClientProductResponse.builder()                .id(cp.getId())                .productName(cp.getProduct().getName())                .productDescription(cp.getProduct().getDescription())                .productType(cp.getProduct().getProductType())                .imageUrl(cp.getProduct().getImageUrl())                .supportPlan(cp.getSupportPlan())                .purchasedDate(cp.getPurchasedDate())                .planEndDate(cp.getPlanEndDate())                .availableMinutes(cp.getAvailableMinutes())                .totalMinutes(cp.getTotalMinutes())                .status(cp.getStatus().name()) // 👈 ဤနေရာတွင် boolean အစား Enum ၏ စာသားကို ပြောင်းလဲပေးပို့ပါသည်                .build();    }}